// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(address logAddr) public {
        // finalize configuration: after Initialized(), SetLogFile is permanently locked
        c.SetMinSum(1);
        c.Initialized();
        // any post-initialization SetLogFile attempt must revert
        bool ok;
        try c.SetLogFile(logAddr) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "SetLogFile must revert after initialization");
    }
}
